75	/**
76	 * Maintains mapping from skeleton file id to external bootstrap file.
77	 * It maintains 2 physical indices.
78	 *  (a) At partition granularity to lookup all indices for each partition.
79	 *  (b) At file-group granularity to lookup bootstrap mapping for an individual file-group.
80	 *
81	 * This implementation uses HFile as physical storage of index. FOr the initial run, bootstrap
82	 * mapping for the entire dataset resides in a single file but care has been taken in naming
83	 * the index files in the same way as Hudi data files so that we can reuse file-system abstraction
84	 * on these index files to manage multiple file-groups.
85	 */
86	
87	public class HFileBootstrapIndex extends BootstrapIndex {
88	
89	  private static final long serialVersionUID = 1L;
90	
91	  private static final Logger LOG = LoggerFactory.getLogger(HFileBootstrapIndex.class);
92	
93	  public static final String BOOTSTRAP_INDEX_FILE_ID = "00000000-0000-0000-0000-000000000000-0";
94	
95	  private static final String PARTITION_KEY_PREFIX = "part";
96	  private static final String FILE_ID_KEY_PREFIX = "fileid";
97	  private static final String KEY_VALUE_SEPARATOR = "=";
98	  private static final String KEY_PARTS_SEPARATOR = ";";
99	  // This is part of the suffix that HFIle appends to every key
100	  private static final String HFILE_CELL_KEY_SUFFIX_PART = "//LATEST_TIMESTAMP/Put/vlen";
101	
102	  // Additional Metadata written to HFiles.
103	  public static final String INDEX_INFO_KEY_STRING = "INDEX_INFO";
104	  public static final byte[] INDEX_INFO_KEY = getUTF8Bytes(INDEX_INFO_KEY_STRING);
105	
106	  private final boolean isPresent;
107	
108	  public HFileBootstrapIndex(HoodieTableMetaClient metaClient) {
109	    super(metaClient);
110	    StoragePath indexByPartitionPath = partitionIndexPath(metaClient);
111	    StoragePath indexByFilePath = fileIdIndexPath(metaClient);
112	    try {
113	      HoodieStorage storage = metaClient.getStorage();
114	      // The metadata table is never bootstrapped, so the bootstrap index is always absent
115	      // for the metadata table.  The fs.exists calls are avoided for metadata table.
116	      isPresent = !metaClient.isMetadataTable() && storage.exists(indexByPartitionPath) && storage.exists(indexByFilePath);
117	    } catch (IOException ioe) {
118	      throw new HoodieIOException(ioe.getMessage(), ioe);
119	    }
120	  }
121	
122	  /**
123	   * Returns partition-key to be used in HFile.
124	   * @param partition Partition-Path
125	   * @return
126	   */
127	  private static String getPartitionKey(String partition) {
128	    return getKeyValueString(PARTITION_KEY_PREFIX, partition);
129	  }
130	
131	  /**
132	   * Returns file group key to be used in HFile.
